#: The one organisation of the first version. Kept here rather than
#: imported, so the migration means the same thing after the code changes.
ORGANISATION_NAME = "Turva"

#: Every competency an organisation admin holds, as the catalogue had them
#: when this migration was written.
ADMIN_COMPETENCIES = [
    "grant_agent_permissions",
    "manage_members",
    "manage_spaces",
]


def make_the_organisation(apps, schema_editor):
    """Make the Turva team's organisation, and make any account its admin.

    The first account can be made before this migration runs, with
    `just first-account`, and was promised admin once organisations came.
    `create_first_account` refuses a second, so there is at most one.
    """
    OrgUnit = apps.get_model("organisations", "OrgUnit")
    OrgUnitMember = apps.get_model("organisations", "OrgUnitMember")
    CompetencyGrant = apps.get_model("organisations", "CompetencyGrant")
    AuditEvent = apps.get_model("audit", "AuditEvent")
    User = apps.get_model("accounts", "User")

    # Not audited: Django's own django_migrations table records that this
    # ran, and when. What it gives a person is audited below, because that
    # is power somebody now holds.
    organisation = OrgUnit.objects.create(
        name=ORGANISATION_NAME, type="organisation"
    )

    for user in User.objects.order_by("pk"):
        OrgUnitMember.objects.create(user=user, org_unit=organisation)
        AuditEvent.objects.create(
            action="member_added",
            detail={
                "user": user.pk,
                "org_unit": organisation.pk,
                "by": "migration",
            },
        )

        for competency in ADMIN_COMPETENCIES:
            CompetencyGrant.objects.create(
                user=user, org_unit=organisation, competency=competency
            )
            AuditEvent.objects.create(
                action="competency_granted",
                detail={
                    "user": user.pk,
                    "competency": competency,
                    "org_unit": organisation.pk,
                    "by": "migration",
                },
            )


def remove_the_organisation(apps, schema_editor):
    """Undo it. The audit entries stay: nothing removes those."""
    for name in ["CompetencyGrant", "OrgUnitMember", "OrgUnit"]:
        apps.get_model("organisations", name).objects.all().delete()


